  function workspaceNav(){return '<nav class="directory-workspace-nav" aria-label="Secciones del perfil"><button type="button" data-directory-area="profile" aria-current="'+(state.area==='profile')+'"><span>1</span><strong>Ficha</strong><small>Tu presentación</small></button><button type="button" data-directory-area="cases" aria-current="'+(state.area==='cases')+'"><span>2</span><strong>Casos</strong><small>Resultados autorizados</small></button><button type="button" data-directory-area="reviews" aria-current="'+(state.area==='reviews')+'"><span>3</span><strong>Reseñas</strong><small>Opiniones verificadas</small></button></nav>';}
  function progressHero(pro,p){var progress=profileProgress(pro,p),missing=progress.missing.slice(0,3).map(function(x){return x.label.toLowerCase();});return '<section class="directory-progress-card" aria-label="Avance de la ficha"><div class="directory-progress-ring" style="--progress:'+progress.percent+'"><strong data-progress-percent>'+progress.percent+'%</strong><span>completo</span></div><div class="directory-progress-copy"><span>TU PERFIL, PASO A PASO</span><h3>'+(progress.complete?'Tu ficha ya tiene lo necesario':'Cada dato mejora la confianza del paciente')+'</h3><p data-progress-message>'+(missing.length?(progress.complete?'Puedes mejorarla agregando ':'Continúa con ')+esc(missing.join(', '))+'.':'Revisa la vista previa y envía la ficha cuando estés listo.')+'</p><div class="directory-progress-track"><i data-progress-bar style="width:'+progress.percent+'%"></i></div></div><div class="directory-progress-reward"><span>Al terminar podrás</span><strong>Compartir enlace y QR</strong><small>y recibir solicitudes de cita</small></div></section>';}
  function readinessChecklist(progress){var stepNames=['Tu identidad','Tu presentación','Señales de confianza'];var groups=[0,1,2].map(function(s){return{step:s,name:stepNames[s],items:progress.items.filter(function(x){return x.step===s;})};});var complete=progress.complete;var header='<div class="directory-checklist-header" data-ready="'+complete+'"><span>'+(complete?'✓':'→')+'</span><div><strong>'+(complete?'La ficha tiene lo necesario':'Estos campos hacen la diferencia')+'</strong><p>'+(complete?'Revisa la vista previa y cuando estés listo, publica tu ficha.':'Los marcados con ● son necesarios para publicar.')+'</p></div></div>';var list=groups.map(function(g){var anyMissing=g.items.some(function(x){return !x.done;});var rows=g.items.map(function(item){return'<li class="directory-checklist-item" data-done="'+item.done+'" data-required="'+(item.required||false)+'"><span class="directory-checklist-icon">'+(item.done?'✓':'●')+'</span><span>'+esc(item.label)+(item.required&&!item.done?' <em>requerido</em>':'')+'</span></li>';}).join('');return'<div class="directory-checklist-group"><div class="directory-checklist-group-head"><span>'+esc(g.name)+'</span>'+(anyMissing?'<button type="button" class="directory-checklist-go" data-profile-step="'+g.step+'">Ir a completar →</button>':'')+'</div><ul>'+rows+'</ul></div>';}).join('');return header+'<div class="directory-checklist">'+list+'</div>';}
  function photoUrl(path){if(!path||!window.sb)return'';var r=window.sb.storage.from('smyl-professional-public').getPublicUrl(path);return r&&r.data&&r.data.publicUrl||'';}
  function renderList(){var host=document.getElementById('directory-list');if(!host)return;host.innerHTML=state.professionals.map(function(p){var f=profileFor(p.id),active=p.id===state.selected,photo=photoUrl(f.photo_path),progress=profileProgress(p,f);return '<button type="button" class="directory-person" data-professional="'+p.id+'" aria-current="'+active+'">'+(photo?'<img src="'+esc(photo)+'" alt="">':'<span>'+esc(initials(p.display_name))+'</span>')+'<div><strong>'+esc(p.display_name)+'</strong><small>'+esc(p.specialty||'Odontología general')+'</small><i data-status="'+esc(f.status||'draft')+'">'+progress.percent+'% · '+esc(statusLabel(f.status))+'</i></div></button>';}).join('');host.querySelectorAll('[data-professional]').forEach(function(b){b.onclick=function(){state.selected=b.dataset.professional;state.area='profile';state.profileStep=0;renderAll();};});if(!state.professionals.length)host.innerHTML='<div class="directory-empty">Primero agrega un profesional desde Mi clínica.</div>';}
