    var percent=Math.round(checks.filter(Boolean).length/checks.length*100),required=[checks[0],checks[1],checks[2],checks[3],checks[5],checks[11]].every(Boolean),missing=labels.filter(function(_,index){return !checks[index];}).slice(0,3);
    var number=document.querySelector('[data-progress-percent]'),bar=document.querySelector('[data-progress-bar]'),messageEl=document.querySelector('[data-progress-message]'),ring=document.querySelector('.directory-progress-ring'),finish=document.querySelector('[data-profile-finish]');
